using FamilyVeda.Application.Records;
using FamilyVeda.Domain.Common;
using FamilyVeda.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace FamilyVeda.Api.Background;

/// <summary>Reads queued lab reports one at a time, off the HTTP request (same pattern as TriageWorker).</summary>
public sealed class LabExtractionWorker(
    ILabExtractionQueue workQueue,
    IServiceScopeFactory scopeFactory,
    ILogger<LabExtractionWorker> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        Queue<Guid> recovered;
        try
        {
            recovered = await RecoverInterruptedReportsAsync(stoppingToken);
        }
        catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
        {
            return;
        }
        catch (Exception exception)
        {
            logger.LogError(exception, "Lab extraction recovery failed; continuing with new reads only.");
            recovered = new Queue<Guid>();
        }
        while (!stoppingToken.IsCancellationRequested)
        {
            Guid? reportId = null;
            try
            {
                reportId = recovered.Count > 0 ? recovered.Dequeue() : await workQueue.DequeueAsync(stoppingToken);
                await ProcessAsync(reportId.Value, stoppingToken);
            }
            catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
            {
                break;
            }
            catch (Exception exception)
            {
                logger.LogError(exception, "Lab extraction worker failed while reading a queued report.");
                if (reportId.HasValue) await MarkFailedAsync(reportId.Value);
            }
        }
    }

    internal async Task ProcessAsync(Guid reportId, CancellationToken stoppingToken)
    {
        await using var scope = scopeFactory.CreateAsyncScope();
        var service = scope.ServiceProvider.GetRequiredService<ILabExtractionService>();
        await service.RunQueuedAsync(reportId, stoppingToken);
    }

    /// <summary>Reports left Processing by a restart: recent ones are read again (oldest first), stale ones fail as OCR_INTERRUPTED.</summary>
    internal async Task<Queue<Guid>> RecoverInterruptedReportsAsync(CancellationToken cancellationToken)
    {
        await using var scope = scopeFactory.CreateAsyncScope();
        var dbContext = scope.ServiceProvider.GetRequiredService<AppDbContext>();
        var reports = await dbContext.LabReports
            .Where(x => x.OcrStatus == OcrStatus.Processing)
            .OrderBy(x => x.UpdatedAt)
            .ToListAsync(cancellationToken);
        var recovered = new Queue<Guid>();
        var now = DateTimeOffset.UtcNow;
        foreach (var report in reports)
        {
            if (now - report.UpdatedAt < OcrFailureCodes.StaleProcessingAfter)
            {
                recovered.Enqueue(report.Id);
                continue;
            }
            report.OcrStatus = OcrStatus.Failed;
            report.OcrErrorCode = OcrFailureCodes.Interrupted;
        }
        await dbContext.SaveChangesAsync(cancellationToken);
        if (recovered.Count > 0) logger.LogInformation("Re-queued {Count} lab report read(s) interrupted by a restart.", recovered.Count);
        return recovered;
    }

    private async Task MarkFailedAsync(Guid reportId)
    {
        try
        {
            await using var scope = scopeFactory.CreateAsyncScope();
            var dbContext = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var report = await dbContext.LabReports.SingleOrDefaultAsync(x => x.Id == reportId);
            if (report is null || report.OcrStatus != OcrStatus.Processing) return;
            report.OcrStatus = OcrStatus.Failed;
            report.OcrErrorCode = OcrFailureCodes.Failed;
            await dbContext.SaveChangesAsync();
        }
        catch (Exception exception)
        {
            logger.LogError(exception, "Could not mark a failed lab report read.");
        }
    }
}
